import type { Metadata } from "next";
import Link from "@/components/i18n/LocaleLink";
import Image from "next/image";
import { notFound } from "next/navigation";
import FetchErrorFallback from "@/components/public/FetchErrorFallback";
import PageShell from "@/components/public/PageShell";
import { BreadcrumbJsonLd } from "@/components/public/JsonLd";
import { Breadcrumbs, ImageSlot, muted } from "@/components/public/ui";
import { fetchProject, fetchProjects } from "@/lib/api";
import { toLocale } from "@/lib/i18n/config";
import { getDictionary } from "@/lib/i18n/dictionaries";
import { routes } from "@/lib/routes";
import { buildMetadata } from "@/lib/seo";
import { getProjectBreadcrumb } from "./content";

export const revalidate = 60;

type Params = { locale: string; slug: string };

const statusChrome: Record<string, { bg: string; fg: string }> = {
  success: { bg: "var(--hz-success-bg)", fg: "var(--hz-success)" },
  info: { bg: "var(--hz-info-bg)", fg: "var(--hz-info)" },
  neutral: { bg: "var(--color-neutral-100)", fg: "var(--color-neutral-800)" },
};

const timelineDot: Record<string, string> = {
  success: "var(--hz-success)",
  info: "var(--hz-info)",
  warning: "var(--hz-warning)",
  danger: "var(--hz-danger)",
  critical: "var(--hz-critical)",
  neutral: "var(--color-neutral-400)",
};

export async function generateStaticParams({
  params: { locale },
}: {
  params: { locale: string };
}) {
  const { data: projects } = await fetchProjects({ locale: toLocale(locale), perPage: 50 });
  return projects.map((p) => ({ slug: p.slug }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<Params>;
}): Promise<Metadata> {
  const { locale, slug } = await params;
  const loc = toLocale(locale);
  const { common, pages } = getDictionary(loc);
  // A thrown (non-404) fetch failure degrades the same as "not found" here —
  // metadata has no meaningful title to offer either way. The page body's
  // own fetch (below) is what decides notFound() vs. the error boundary.
  const p = await fetchProject(slug, loc).catch(() => null);
  if (!p) {
    return { title: pages.meta.projectFallback, robots: { index: false } };
  }
  return buildMetadata({
    locale: loc,
    title: p.title,
    description: p.desc,
    path: `/projects/${slug}`,
    images: p.image ? [p.image] : undefined,
    type: "article",
    siteName: common.siteShort,
  });
}

export default async function ProjectDetailPage({
  params,
}: {
  params: Promise<Params>;
}) {
  const { locale: rawLocale, slug } = await params;
  const locale = toLocale(rawLocale);
  const { pages } = getDictionary(locale);
  const projectBreadcrumb = getProjectBreadcrumb(locale);
  // Non-404 fetch failures are an expected-error case (see
  // FetchErrorFallback) — handled inline, not left to throw.
  let p;
  try {
    p = await fetchProject(slug, locale);
  } catch {
    return (
      <PageShell active="" locale={locale}>
        <FetchErrorFallback locale={locale} />
      </PageShell>
    );
  }

  if (!p) {
    notFound();
  }

  const meta = [
    { label: pages.projectDetail.customer, value: p.customer },
    { label: pages.projectDetail.partners, value: p.partner },
    { label: pages.projectDetail.budget, value: p.budget },
    { label: pages.projectDetail.term, value: p.years },
  ].filter((m): m is { label: string; value: string } => Boolean(m.value));

  const chrome = statusChrome[p.status_tone] ?? statusChrome.neutral;
  const goals = p.goals ?? [];
  const timeline = p.timeline ?? [];

  // Развёрнутое описание проекта — санитайзенный HTML из редактора CMS.
  const bodyHtml = p.body ?? "";
  const bodyIsHtml = /<[a-z][\s\S]*>/i.test(bodyHtml);

  const { data: allProjects } = await fetchProjects({ locale, perPage: 50 });
  const related = allProjects.filter((r) => r.slug !== slug).slice(0, 3);

  return (
    <PageShell active="" locale={locale}>
      <BreadcrumbJsonLd
        items={[
          { label: projectBreadcrumb.home, href: routes.home },
          { label: projectBreadcrumb.projects, href: routes.projects },
          { label: p.title },
        ]}
        locale={locale}
      />
      <Breadcrumbs
        items={[
          { label: projectBreadcrumb.home, href: routes.home },
          { label: projectBreadcrumb.projects, href: routes.projects },
          { label: p.title },
        ]}
      />

      {/* Шапка проекта */}
      <section
        aria-label={pages.projectDetail.aria}
        className="blueprint mt-5 flex flex-col gap-3 px-[26px] py-6"
      >
        <div className="flex flex-wrap items-center gap-2">
          <span
            className="tag font-semibold"
            style={{ background: chrome.bg, color: chrome.fg }}
          >
            {p.status}
          </span>
          {p.years && <span className="tag tag-neutral">{p.years}</span>}
          {p.code && <span className="tag tag-outline">{p.code}</span>}
        </div>
        <h1 className="m-0 text-[32px] leading-[1.12]">{p.title}</h1>
        {meta.length > 0 && (
          <div className="grid grid-cols-4 gap-[14px] border-t border-[var(--color-divider)] pt-[14px] max-[920px]:grid-cols-2 max-[560px]:grid-cols-1">
            {meta.map((m) => (
              <div key={m.label}>
                <h6 className="m-0 mb-1" style={{ color: muted(55) }}>
                  {m.label}
                </h6>
                <span className="text-[13.5px]">{m.value}</span>
              </div>
            ))}
          </div>
        )}
      </section>

      <div className="mt-7 grid grid-cols-[minmax(0,1.9fr)_minmax(260px,1fr)] items-start gap-9 max-[920px]:grid-cols-1">
        {/* Основная колонка */}
        <div className="min-w-0 max-w-[74ch]">
          {/* Цели и задачи */}
          <section aria-label={pages.projectDetail.goalsAria}>
            <h2 className="text-[22px] uppercase tracking-[.02em]">
              {pages.projectDetail.goalsTitle}
            </h2>
            {p.desc && (
              <p className="text-[15px] leading-[1.65]">{p.desc}</p>
            )}
            {goals.length > 0 && (
              <div className="flex flex-col">
                {goals.map((g, i) => (
                  <div
                    key={i}
                    className="flex gap-[14px] py-3"
                    style={{
                      borderBottom:
                        i === goals.length - 1
                          ? undefined
                          : "1px solid var(--color-divider)",
                    }}
                  >
                    <span
                      className="min-w-[28px] text-[19px] font-semibold [font-family:var(--font-heading)]"
                      style={{ color: "var(--color-accent-700)" }}
                    >
                      {String(i + 1).padStart(2, "0")}
                    </span>
                    <span className="text-[14.5px] leading-[1.55]">{g}</span>
                  </div>
                ))}
              </div>
            )}
          </section>

          {/* Подробнее о проекте */}
          {bodyIsHtml && (
            <section aria-label={pages.projectDetail.moreTitle} className="mt-7">
              <h2 className="text-[22px] uppercase tracking-[.02em]">
                {pages.projectDetail.moreTitle}
              </h2>
              <div
                className="article-prose"
                dangerouslySetInnerHTML={{ __html: bodyHtml }}
              />
            </section>
          )}

          {/* Ход реализации */}
          {timeline.length > 0 && (
            <section aria-label={pages.projectDetail.timelineTitle} className="mt-7">
              <h2 className="text-[22px] uppercase tracking-[.02em]">
                {pages.projectDetail.timelineTitle}
              </h2>
              <div className="flex flex-col border-l border-[var(--color-divider)]">
                {timeline.map((t, i) => (
                  <div key={i} className="relative py-2.5 pl-5">
                    <span
                      className="absolute h-2 w-2 rounded-full"
                      style={{
                        left: "-4.5px",
                        top: "16px",
                        background: timelineDot[t.tone] ?? timelineDot.neutral,
                      }}
                    />
                    <span className="text-xs" style={{ color: muted(55) }}>
                      {t.date}
                    </span>
                    <p className="m-0 mt-0.5 text-sm">{t.text}</p>
                  </div>
                ))}
              </div>
            </section>
          )}

          {/* Фото */}
          <section aria-label={pages.projectDetail.photoAria} className="mt-7">
            <figure className={`blueprint mb-1.5 h-[300px] ${p.image ? "duotone" : ""}`}>
              {p.image ? (
                <Image
                  src={p.image}
                  alt={p.title}
                  fill
                  sizes="(max-width: 920px) 100vw, 720px"
                  style={{ objectFit: "cover" }}
                />
              ) : (
                <ImageSlot label={pages.projectDetail.photoLabel} />
              )}
            </figure>
          </section>
        </div>

        {/* Сайдбар */}
        <aside className="flex flex-col gap-5">
          {/* Дирекция проекта */}
          {p.direction &&
            (p.direction.address ||
              p.direction.phone ||
              p.direction.email) && (
              <div className="blueprint flex flex-col gap-2 p-[18px]">
                <h6 className="m-0" style={{ color: muted(55) }}>
                  {pages.projectDetail.direction}
                </h6>
                <p
                  className="m-0 text-[13px] leading-[1.55]"
                  style={{ color: muted(70) }}
                >
                  {p.direction.address && (
                    <span>
                      {p.direction.address}
                      <br />
                    </span>
                  )}
                  {p.direction.phone && (
                    <a
                      href={`tel:${p.direction.phone.replace(/[^+\d]/g, "")}`}
                      style={{ color: "var(--color-accent-700)" }}
                    >
                      {p.direction.phone}
                    </a>
                  )}
                  {p.direction.email && ` · ${p.direction.email}`}
                </p>
              </div>
            )}

          {/* Другие проекты */}
          {related.length > 0 && (
            <div>
              <h6 className="m-0 mb-2.5" style={{ color: muted(55) }}>
                {pages.projectDetail.otherProjects}
              </h6>
              {related.map((r, i) => (
                <Link
                  key={r.slug}
                  href={routes.project(r.slug)}
                  className="row-link block py-2.5 text-[15px] font-semibold [font-family:var(--font-heading)]"
                  style={{
                    textDecoration: "none",
                    color: "inherit",
                    borderBottom:
                      i === related.length - 1
                        ? undefined
                        : "1px solid var(--color-divider)",
                  }}
                >
                  {r.title}
                </Link>
              ))}
            </div>
          )}
        </aside>
      </div>
    </PageShell>
  );
}
